"use client"

import Image from "next/image"
import * as React from "react"

import { Avatar, AvatarFallback } from "@/components/ui/avatar"
import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from "@/components/ui/breadcrumb"
import { Button } from "@/components/ui/button"
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "@/components/ui/collapsible"
import { Separator } from "@/components/ui/separator"
import {
  Sidebar,
  SidebarContent,
  SidebarGroup,
  SidebarGroupContent,
  SidebarGroupLabel,
  SidebarHeader,
  SidebarInset,
  SidebarMenu,
  SidebarMenuAction,
  SidebarMenuButton,
  SidebarMenuItem,
  SidebarProvider,
  SidebarTrigger,
  useSidebar,
} from "@/components/ui/sidebar"
import { cn } from "@/lib/utils"
import {
  BatchCallsIcon,
  BuildingIcon,
  ChevronDownIcon,
  ConversationsIcon,
  DashboardIcon,
  DeveloperDocsIcon,
  GlobalPromptsIcon,
  IntegrationsIcon,
  KeyIcon,
  KnowledgeIcon,
  MessagingIcon,
  MessagingSettingsIcon,
  MobileIcon,
  ModelsIcon,
  NewItemIcon,
  PersonasIcon,
  PlaygroundIcon,
  QualityIcon,
  ReportsIcon,
  RolesIcon,
  ScenariosIcon,
  SettingsIcon,
  TasksIcon,
  TelephonyIcon,
  TemplateIcon,
  VariablesIcon,
  VoiceLibraryIcon,
  WebhooksIcon,
} from "@/components/app-shell-icons"

/**
 * The app around any mockup screen, shared by every mockup that wants the
 * product chrome: an inset sidebar over a tinted page, and a header carrying
 * the breadcrumb and the account. Pass `active` to highlight the nav item the
 * screen lives under.
 *
 * Playground sits above the groups rather than inside one — it is the entry
 * point, not a build step. Configuration starts closed because it is the group
 * you visit once and then leave alone.
 */

interface NavItem {
  /** Label for the hover "+", on the two things you create most. */
  action?: string
  icon: React.ComponentType
  title: string
}

const PLAYGROUND: NavItem = { icon: PlaygroundIcon, title: "Playground" }

const NAV: { defaultOpen: boolean; items: NavItem[]; label: string }[] = [
  {
    defaultOpen: true,
    label: "Agents",
    items: [
      { action: "New persona", icon: PersonasIcon, title: "Personas" },
      { action: "New scenario", icon: ScenariosIcon, title: "Scenarios" },
      { icon: KnowledgeIcon, title: "Knowledge Bases" },
      { icon: BatchCallsIcon, title: "Batch Calls" },
      { icon: TemplateIcon, title: "Scenario Templates" },
      { icon: GlobalPromptsIcon, title: "Global Prompts" },
      { icon: VoiceLibraryIcon, title: "Voice Library" },
    ],
  },
  {
    defaultOpen: true,
    label: "Monitor",
    items: [
      { icon: DashboardIcon, title: "Dashboard" },
      { icon: ConversationsIcon, title: "Conversations" },
      { icon: MessagingIcon, title: "Messaging" },
      { icon: QualityIcon, title: "Quality Dashboard" },
      { icon: ReportsIcon, title: "Reports" },
      { icon: TasksIcon, title: "Tasks" },
    ],
  },
  {
    defaultOpen: false,
    label: "Configuration",
    items: [
      { icon: KeyIcon, title: "API Keys" },
      { icon: VariablesIcon, title: "Variables" },
      { icon: WebhooksIcon, title: "Webhooks" },
      { icon: IntegrationsIcon, title: "Integrations" },
      { icon: DeveloperDocsIcon, title: "Developer Docs" },
      { icon: BuildingIcon, title: "Organizations" },
      /* DES-170. Roles are platform-wide and Sarj-only in Phase 1, so they sit
         beside Organizations rather than inside one. */
      { icon: RolesIcon, title: "Roles" },
      { icon: MobileIcon, title: "Phone Numbers" },
      /* DES-169. The catalog needs a home in the nav, and Configuration is
         where the other platform-wide, Sarj-staff-only surfaces already sit. */
      { icon: ModelsIcon, title: "Models" },
      { icon: TelephonyIcon, title: "Telephony" },
      { icon: SettingsIcon, title: "Global Settings" },
      { icon: MessagingSettingsIcon, title: "Messaging Settings" },
    ],
  },
]

function NavLink({
  active,
  item,
  onNavigate,
}: {
  active: boolean
  item: NavItem
  onNavigate?: (title: string) => void
}) {
  return (
    <SidebarMenuItem>
      <SidebarMenuButton
        /* Two differences from the primitive's defaults, both as the app has
           them: hover lands on the neutral `accent` rather than the purple
           `sidebar-accent`, and the active item carries a hairline of its own
           foreground so the filled pill reads as a border, not just a wash. */
        className="border border-transparent hover:bg-accent hover:text-accent-foreground data-active:border-sidebar-accent-foreground/10"
        isActive={active}
        tooltip={item.title}
        onClick={() => onNavigate?.(item.title)}
      >
        <item.icon />
        {/* Closing to the rail fades the label out rather than clipping it. */}
        <span className="truncate transition-opacity duration-200 ease-out-cubic group-data-[collapsible=icon]:opacity-0 motion-reduce:transition-none">
          {item.title}
        </span>
      </SidebarMenuButton>
      {/* `rounded-sm` in place of the primitive's `rounded-md` and `right-2` in
          place of `right-1`, both as the app has them.

          The glyph size is deliberately NOT the app's `[&>svg]:size-full`. That
          class works there because its plus is a hand-drawn 20×20 icon whose
          path spans only 6.5→13.5, so filling the box still draws a 7px plus.
          Ours is HugeIcons' PlusSignIcon, whose ink fills 16 of its 24 viewBox
          units — the same class drew a 12px plus, nearly twice the app's.
          `size-2.5` renders it at 10px, putting the drawn plus at 6.7px. */}
      {item.action ? (
        <SidebarMenuAction
          aria-label={item.action}
          className="top-1.5 right-2 rounded-sm border border-input bg-background text-muted-foreground hover:bg-accent hover:text-foreground [&>svg]:size-2.5"
        >
          <NewItemIcon />
        </SidebarMenuAction>
      ) : null}
    </SidebarMenuItem>
  )
}

/**
 * Collapsed to the icon rail there is no room for a section label, so the
 * groups are forced open and the label — the only thing that could close them —
 * is disabled.
 */
function NavGroup({
  active,
  defaultOpen,
  items,
  label,
  onNavigate,
}: {
  active: string
  defaultOpen: boolean
  items: NavItem[]
  label: string
  onNavigate?: (title: string) => void
}) {
  const { state } = useSidebar()
  const isCollapsed = state === "collapsed"
  const [open, setOpen] = React.useState(defaultOpen)

  return (
    <Collapsible
      disabled={isCollapsed}
      onOpenChange={isCollapsed ? undefined : setOpen}
      open={isCollapsed || open}
    >
      <SidebarGroup>
        <SidebarGroupLabel asChild>
          <CollapsibleTrigger className="flex w-full cursor-pointer items-center justify-between hover:bg-accent/50">
            <span>{label}</span>
            <ChevronDownIcon
              className={cn(
                "transition-transform duration-200 ease-out-cubic motion-reduce:transition-none",
                open ? "rotate-0" : "-rotate-90",
              )}
            />
          </CollapsibleTrigger>
        </SidebarGroupLabel>
        <CollapsibleContent>
          <SidebarGroupContent>
            <SidebarMenu>
              {items.map((item) => (
                <NavLink
                  active={item.title === active}
                  item={item}
                  key={item.title}
                  onNavigate={onNavigate}
                />
              ))}
            </SidebarMenu>
          </SidebarGroupContent>
        </CollapsibleContent>
      </SidebarGroup>
    </Collapsible>
  )
}

/** Breadcrumb start, account end — the row every page in the app sits under. */
export function AppHeader({
  actions,
  trail,
  showSettings,
}: {
  /** Replaces the account row entirely. The design-system page uses it to
   *  carry the way back to the index; a mockup leaves it off and gets the
   *  row the app itself shows. */
  actions?: React.ReactNode
  /** Crumbs after Home. The last is the page; earlier ones are links. */
  trail: readonly string[]
  showSettings?: boolean
}) {
  return (
    <header className="flex h-16 shrink-0 items-center justify-between gap-4 px-4">
      <Breadcrumb>
        {/* The app spaces its crumbs at 2.5; the primitive ships 1.5. */}
        <BreadcrumbList className="gap-2.5">
          <BreadcrumbItem>
            <BreadcrumbLink href="#">Home</BreadcrumbLink>
          </BreadcrumbItem>
          {trail.map((crumb, index) => (
            <React.Fragment key={crumb}>
              <BreadcrumbSeparator />
              <BreadcrumbItem>
                {index === trail.length - 1 ? (
                  <BreadcrumbPage>{crumb}</BreadcrumbPage>
                ) : (
                  <BreadcrumbLink href="#">{crumb}</BreadcrumbLink>
                )}
              </BreadcrumbItem>
            </React.Fragment>
          ))}
        </BreadcrumbList>
      </Breadcrumb>

      <div className="flex shrink-0 items-center gap-2">
        {actions ?? (
          <>
            <Button size="sm" variant="outline">
              <DeveloperDocsIcon />
              Developer Doc
            </Button>
            {/* The same allowlist the nav reads. The app has this gear on its own
            check today, which is how an admin gets a second dead end to the
            page the sidebar already sent them to. */}
            {showSettings ? (
              <Button
                aria-label="Global settings"
                size="icon-sm"
                variant="outline"
              >
                <SettingsIcon />
              </Button>
            ) : null}
            {/* Wrapped, rather than given `self-center`: the primitive ships
            `data-vertical:self-stretch`, and an attribute variant outranks a
            plain utility, so the rule stretched to the 28px row, got held to
            h-4, and settled at the top of it — 6px above the centre the buttons
            and the avatar share. Inside a wrapper of its own the flex line is
            the rule's own height, so stretching changes nothing and the wrapper
            is what the header centres. */}
            <div className="flex items-center">
              <Separator className="mx-1 h-4" orientation="vertical" />
            </div>
            {/* A rounded square at the same radius and height as the two buttons,
            not a circle. The app's account button is Clerk's, and Clerk does not
            inherit the app's CSS vars — so the real header sets its avatar
            radius to a 0.625rem literal, which is `--radius`, which is
            `rounded-lg`. A circle here is the one thing in this row that would
            not be in the app. `after:` and the fallback carry the primitive's
            own `rounded-full`, so both have to be squared off with it. */}
            <Avatar className="size-7 rounded-lg after:rounded-lg">
              <AvatarFallback className="rounded-lg">TA</AvatarFallback>
            </Avatar>
          </>
        )}
      </div>
    </header>
  )
}

export function AppShell({
  active,
  breadcrumb,
  hiddenItems,
  onNavigate,
  children,
}: {
  /** Title of the sidebar item this screen lives under, e.g. "Personas". */
  active: string
  /** Crumbs after Home; a bare string is a single one. Defaults to `active`. */
  breadcrumb?: string | readonly string[]
  /**
   * Nav item titles this viewer's role cannot open, so the menu holds only
   * what they can reach. Omit it and the nav is the full one, which is what
   * every other mockup wants.
   */
  hiddenItems?: readonly string[]
  /** Called with a nav item's title when it is clicked, so a mockup can make
   * the destinations it covers actually switch. Items it ignores stay inert. */
  onNavigate?: (title: string) => void
  children: React.ReactNode
}) {
  const hidden = new Set(hiddenItems ?? [])
  const groups = NAV.map((group) => ({
    ...group,
    items: group.items.filter((item) => !hidden.has(item.title)),
  })).filter((group) => group.items.length > 0)

  return (
    /* The app sizes its sidebar at 15rem; the shadcn primitive ships 16rem.
       Set here rather than in the primitive, which is generated. */
    <SidebarProvider
      className="min-h-0 flex-1"
      style={{ "--sidebar-width": "15rem" } as React.CSSProperties}
    >
      {/* The sidebar pins to the viewport as it does in the app, so it clears
          the mockup shell's own header rather than sliding under it. */}
      <Sidebar className="pt-12" collapsible="icon" variant="inset">
        <SidebarHeader className="px-2 pt-2 pb-1">
          <div className="flex items-center justify-between group-data-[state=collapsed]:justify-center">
            {/* 56×32 is the size the app's own header renders it at. */}
            <Image
              alt="sarj.ai"
              className="group-data-[state=collapsed]:hidden"
              height={32}
              priority
              src="/logo.png"
              width={56}
            />
            <SidebarTrigger className="size-8 rounded-md text-muted-foreground hover:bg-accent hover:text-foreground [&>svg]:size-5" />
          </div>
        </SidebarHeader>

        <SidebarContent>
          <SidebarGroup className="pt-2 pb-0">
            <SidebarGroupContent>
              <SidebarMenu>
                <NavLink
                  active={PLAYGROUND.title === active}
                  item={PLAYGROUND}
                  onNavigate={onNavigate}
                />
              </SidebarMenu>
            </SidebarGroupContent>
          </SidebarGroup>

          {groups.map((group, index) => (
            <React.Fragment key={group.label}>
              {/* The rail hides section labels, so a rule stands in for the
                  grouping those labels carry when the nav is open. */}
              {index > 0 ? (
                <div className="mx-2 my-1 hidden h-px shrink-0 bg-sidebar-border group-data-[collapsible=icon]:block" />
              ) : null}
              <NavGroup
                active={active}
                /* A closed group hiding the item the screen is on reads as the
                   nav having lost its place, so the active item's group opens
                   regardless of where the group would otherwise start. */
                defaultOpen={
                  group.defaultOpen ||
                  group.items.some((item) => item.title === active)
                }
                items={group.items}
                label={group.label}
                onNavigate={onNavigate}
              />
            </React.Fragment>
          ))}
        </SidebarContent>
      </Sidebar>

      <SidebarInset className="min-w-0 overflow-hidden">
        <AppHeader
          trail={
            breadcrumb === undefined
              ? [active]
              : typeof breadcrumb === "string"
                ? [breadcrumb]
                : breadcrumb
          }
          showSettings={!hidden.has("Global Settings")}
        />
        {/* No gutter here: the page owns its p-3 lg:p-4, matching the header. */}
        <div className="min-h-0 flex-1 overflow-auto">{children}</div>
      </SidebarInset>
    </SidebarProvider>
  )
}

"use client"

import * as React from "react"

import { toast } from "sonner"

import { Alert, AlertDescription } from "@/components/ui/alert"
import { Button } from "@/components/ui/button"
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog"
import { Field, FieldDescription, FieldLabel } from "@/components/ui/field"
import { Input } from "@/components/ui/input"
import {
  InputGroup,
  InputGroupAddon,
  InputGroupButton,
  InputGroupInput,
} from "@/components/ui/input-group"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectSeparator,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { Spinner } from "@/components/ui/spinner"
import {
  formatDate,
  mintSecret,
  NOW,
  prefixOf,
  READ_ONLY_SCOPES,
  scopeSummary,
  type ConnectedApp,
  type Permission,
  type Token,
} from "@/lib/connected-apps-data"
import { ScopePicker } from "@/components/connected-apps/scope-picker"
import {
  CopiedIcon,
  CopyTokenIcon,
  NearExpiryIcon,
} from "@/components/connected-apps/icons"

const EXPIRY_CHOICES = [
  { days: 30, id: "30", label: "In 30 days" },
  { days: 60, id: "60", label: "In 60 days" },
  { days: 90, id: "90", label: "In 90 days" },
  { days: 365, id: "365", label: "In a year" },
]

const NEVER = "never"

function expiryFrom(choice: string): string | null {
  const option = EXPIRY_CHOICES.find((entry) => entry.id === choice)
  if (!option) return null
  return new Date(
    new Date(NOW).getTime() + option.days * 86_400_000,
  ).toISOString()
}

/**
 * Minting a token, and the one moment its secret exists on screen.
 *
 * The platform hands the raw value back exactly once and stores only a hash of
 * it, so this dialog is the whole of the reader's opportunity. That is why it
 * stops being dismissible once the secret is showing: the scrim, Escape and the
 * close button all route through the same check, and there is one way out.
 *
 * Deliberately one dialog rather than a create dialog followed by a reveal
 * dialog. The secret belongs to the thing just created, and a second overlay
 * would let the first one close underneath it — taking the only copy of the
 * value with it.
 */
export function CreateTokenDialog({
  app,
  onCreated,
  onOpenChange,
  open,
}: {
  app: ConnectedApp
  onCreated: (token: Token) => void
  onOpenChange: (open: boolean) => void
  open: boolean
}) {
  /* Lifted out of the body because the parts that dismiss a dialog — the
     scrim, Escape, the close button — belong to the shell, and they all have
     to route through the same check once the secret is on screen. */
  const [locked, setLocked] = React.useState(false)
  const guard = React.useRef<() => void>(() => onOpenChange(false))

  /* Stable identities: the body registers its guard from an effect, so a
     handler rebuilt on every render would re-register on every render. */
  const close = React.useCallback(() => onOpenChange(false), [onOpenChange])
  const registerGuard = React.useCallback(
    (locking: boolean, requestClose: () => void) => {
      setLocked(locking)
      guard.current = requestClose
    },
    [],
  )

  return (
    <Dialog
      onOpenChange={(next) => {
        if (!next && locked) {
          guard.current()
          return
        }
        onOpenChange(next)
      }}
      open={open}
    >
      <DialogContent
        className="sm:max-w-lg"
        onEscapeKeyDown={(event) => {
          if (!locked) return
          /* Escape still asks, rather than being dead — it just gets the
             same answer the Done button gets. */
          event.preventDefault()
          guard.current()
        }}
        onInteractOutside={(event) => {
          if (locked) event.preventDefault()
        }}
        onPointerDownOutside={(event) => {
          if (locked) event.preventDefault()
        }}
        showCloseButton={!locked}
      >
        {/* Keyed on the app so every open starts clean — the phase, the form
            and above all the secret are gone when this unmounts. */}
        <CreateTokenBody
          app={app}
          key={app.id}
          onClose={close}
          onCreated={onCreated}
          onGuardChange={registerGuard}
        />
      </DialogContent>
    </Dialog>
  )
}

type Phase = "form" | "creating" | "revealed" | "confirm-close"

function CreateTokenBody({
  app,
  onClose,
  onCreated,
  onGuardChange,
}: {
  app: ConnectedApp
  onClose: () => void
  onCreated: (token: Token) => void
  onGuardChange: (locked: boolean, requestClose: () => void) => void
}) {
  const [phase, setPhase] = React.useState<Phase>("form")
  const [name, setName] = React.useState("")
  const [scopes, setScopes] = React.useState<Permission[]>(READ_ONLY_SCOPES)
  const [expiry, setExpiry] = React.useState("90")
  const [secret, setSecret] = React.useState("")
  const [copied, setCopied] = React.useState(false)

  const timer = React.useRef<ReturnType<typeof setTimeout> | undefined>(
    undefined,
  )
  React.useEffect(() => () => clearTimeout(timer.current), [])

  /* Sealed from the moment the secret appears until the reader has answered
     for it. The confirm step stays sealed too, so its own close button cannot
     become a third exit that skips the question. "Close anyway" is safe
     because it calls onClose directly rather than going through the shell. */
  const locked = phase === "revealed" || phase === "confirm-close"
  React.useEffect(() => {
    onGuardChange(locked, () => {
      if (copied) onClose()
      else setPhase("confirm-close")
    })
  }, [copied, locked, onClose, onGuardChange])

  const expiresAt = expiryFrom(expiry)
  const canSave = name.trim().length > 0 && scopes.length > 0

  function create() {
    setPhase("creating")

    /* Stands in for the round trip. The secret is minted here rather than
       living on the record, because on the real thing it exists only in this
       response. */
    window.setTimeout(() => {
      const value = mintSecret()
      setSecret(value)
      setPhase("revealed")
      onCreated({
        appId: app.id,
        createdAt: NOW,
        createdBy: "Nawaf Al-Harbi",
        expiresAt,
        id: `tok-${prefixOf(value)}`,
        lastUsedAt: null,
        name: name.trim(),
        prefix: prefixOf(value),
        revokedAt: null,
        scopes,
      })
    }, 700)
  }

  async function copySecret() {
    try {
      await navigator.clipboard.writeText(secret)
      setCopied(true)
      clearTimeout(timer.current)
      timer.current = setTimeout(() => setCopied(false), 2000)
      toast.success("Access token copied", { description: name.trim() })
    } catch {
      /* The clipboard is permission-gated and unavailable on an insecure
         origin. This is the one screen where failing quietly would lose
         something unrecoverable, so the value goes into the toast. */
      toast.error("Could not reach the clipboard", { description: secret })
    }
  }

  /** The only exit once the secret is showing. */
  function attemptClose() {
    if (copied) {
      onClose()
      return
    }
    setPhase("confirm-close")
  }

  if (phase === "confirm-close") {
    return (
      <>
        <DialogHeader>
          <DialogTitle>Close without copying the token?</DialogTitle>
          <DialogDescription>
            This is the only time the secret is shown. Close now and it cannot
            be recovered — the token stays live, so the only way back is to
            revoke it and create another.
          </DialogDescription>
        </DialogHeader>

        <DialogFooter>
          <Button onClick={() => setPhase("revealed")} variant="outline">
            Back to the token
          </Button>
          {/* Not "Discard token" — the token exists and works. Only the
              secret is lost, and the label should not claim otherwise. */}
          <Button onClick={onClose} variant="destructive">
            Close anyway
          </Button>
        </DialogFooter>
      </>
    )
  }

  if (phase === "revealed") {
    return (
      <>
        <DialogHeader>
          <DialogTitle>Your new access token has been created</DialogTitle>
          <DialogDescription>
            Make sure to copy this token now. You will not be able to see it
            again.
          </DialogDescription>
        </DialogHeader>

        <Alert className="bg-warning-tint text-warning-tint-foreground">
          <NearExpiryIcon />
          <AlertDescription className="text-warning-tint-foreground">
            Sarj stores only a hash of this value. Nobody can show it to you a
            second time — not you, not support.
          </AlertDescription>
        </Alert>

        {/* An Input rather than a code block: it is keyboard reachable, it
            selects on focus, and readOnly keeps all of that alive where
            disabled would kill it. `dir="ltr"` so a base64 credential is not
            reordered next to Arabic content. */}
        <InputGroup>
          <InputGroupInput
            aria-label="Access token"
            className="font-mono"
            dir="ltr"
            onCopy={() => setCopied(true)}
            onFocus={(event) => event.currentTarget.select()}
            readOnly
            value={secret}
          />
          <InputGroupAddon align="inline-end">
            <InputGroupButton onClick={copySecret}>
              {copied ? <CopiedIcon /> : <CopyTokenIcon />}
              {copied ? "Copied" : "Copy"}
            </InputGroupButton>
          </InputGroupAddon>
        </InputGroup>

        <p className="text-sm text-muted-foreground">
          <span dir="auto">{name.trim()}</span> · {scopeSummary(scopes)} ·{" "}
          {expiresAt ? `Expires ${formatDate(expiresAt)}` : "Never expires"}
        </p>

        <DialogFooter>
          {/* Never gated on having copied — a reader whose clipboard is
              blocked would be trapped in a dialog they cannot leave. */}
          <Button onClick={attemptClose}>Done</Button>
        </DialogFooter>
      </>
    )
  }

  return (
    <>
      <DialogHeader>
        <DialogTitle>New access token</DialogTitle>
        <DialogDescription>
          This creates a live token for <span dir="auto">{app.name}</span>{" "}
          immediately. The full secret is shown only once, so be ready to copy
          it.
        </DialogDescription>
      </DialogHeader>

      <div className="-mx-1 flex max-h-[60vh] flex-col gap-4 overflow-y-auto px-1">
        <Field>
          <FieldLabel htmlFor="token-name">Name</FieldLabel>
          <Input
            dir="auto"
            id="token-name"
            onChange={(event) => setName(event.target.value)}
            placeholder="Production sync"
            value={name}
          />
          <FieldDescription>
            Name it for where it runs, so you know which one to revoke.
          </FieldDescription>
        </Field>

        <ScopePicker onChange={setScopes} scopes={scopes} />

        <Field>
          <FieldLabel htmlFor="token-expiry">Expires</FieldLabel>
          <Select onValueChange={setExpiry} value={expiry}>
            <SelectTrigger id="token-expiry">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              {EXPIRY_CHOICES.map((option) => (
                <SelectItem key={option.id} value={option.id}>
                  {option.label}
                </SelectItem>
              ))}
              <SelectSeparator />
              {/* Set apart because it is the heavier choice, not the tidy
                  one — a token nobody has to renew is also a token nobody
                  remembers to remove. */}
              <SelectItem value={NEVER}>No expiry</SelectItem>
            </SelectContent>
          </Select>
          <FieldDescription>
            {expiresAt
              ? `Stops working on ${formatDate(expiresAt)}.`
              : "It keeps working until someone revokes it."}
          </FieldDescription>
        </Field>
      </div>

      <DialogFooter>
        <Button onClick={onClose} variant="ghost">
          Cancel
        </Button>
        <Button disabled={!canSave || phase === "creating"} onClick={create}>
          {phase === "creating" ? <Spinner /> : null}
          {phase === "creating" ? "Creating…" : "Create token"}
        </Button>
      </DialogFooter>
    </>
  )
}

